// [1] Validate & quarantine telemetry
// Output 1 = valid reading (msg.payload = clean object)
// Output 2 = quarantined message (for the debug sidebar + dashboard log)
const RANGES = {                         // same plausible ranges as Member 2's schemas.py
    temperature_c: [-40, 250],
    vibration_rms: [0, 100],
    current_a:     [0, 200],
    rpm:           [0, 6000]
};
const topicId = (msg.topic || "").split("/")[3] || null;   // factory/site01/machine/{id}/telemetry
let d;
try {
    d = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    return [null, { topic: msg.topic, payload: { machine_id: topicId, errors: ["invalid JSON"], raw: String(msg.payload).slice(0, 200) } }];
}
const errors = [];
if (!d || typeof d !== "object" || Array.isArray(d)) errors.push("payload is not a JSON object");
else {
    if (typeof d.machine_id !== "string" || !d.machine_id.trim()) errors.push("missing or invalid machine_id");
    if (!d.timestamp || isNaN(Date.parse(d.timestamp))) errors.push("missing or invalid timestamp");
    for (const k in RANGES) {
        const v = d[k];
        if (typeof v !== "number" || !isFinite(v)) errors.push(`missing or non-numeric ${k}`);
        else if (v < RANGES[k][0] || v > RANGES[k][1]) errors.push(`${k}=${v} outside [${RANGES[k]}]`);
    }
}
if (errors.length) {
    const q = { machine_id: (d && d.machine_id) || topicId, errors, raw: JSON.stringify(d).slice(0, 200), received_at: new Date().toISOString() };
    const log = flow.get("quarantine") || [];
    log.unshift(q); flow.set("quarantine", log.slice(0, 20));
    node.status({ fill: "red", shape: "dot", text: `quarantined: ${errors[0]}` });
    return [null, { topic: msg.topic, payload: q }];
}
node.status({ fill: "green", shape: "dot", text: `${d.machine_id} seq ${d.seq}` });
msg.payload = {
    machine_id: d.machine_id.trim(), timestamp: d.timestamp, seq: d.seq,
    machine_status: d.machine_status || "RUNNING",
    temperature_c: d.temperature_c, vibration_rms: d.vibration_rms,
    current_a: d.current_a, rpm: d.rpm
};   // sim_scenario is deliberately dropped: decisions use only the 4 sensors
return [msg, null];

// [2] Analytics engine: smoothing, sliding window, risk score, state, fault cause, TTC (all ASCII strings)
// Outputs: 1 health (MQTT), 2 features (MQTT), 3 alert on state change (MQTT),
//          4 recommended action (MQTT), 5 risk chart, 6 temperature chart, 7 vibration chart
const WINDOW = 20, MIN_SAMPLES = 10, R2_MIN = 0.70;
const ALPHA = 0.3;            // EMA smoothing factor
const PUBLISH_EVERY = 5;      // health/features to Kafka every 5 samples (~5 s)
const CONFIRM = 3;            // a new state must hold 3 samples before it is accepted (no flapping)
const W = { temperature_c: 0.30, vibration_rms: 0.40, current_a: 0.20, rpm: 0.10 };
// higher-is-worse signals: warning above `warn`, critical above `crit`
const HI = { temperature_c: { warn: 70, crit: 80 }, vibration_rms: { warn: 3, crit: 6 }, current_a: { warn: 15, crit: 20 } };
const RPM = { lo: 1400, hi: 1500, band: 50 };   // warning 50 rpm outside, critical beyond that
const SIGNALS = Object.keys(W);
const CAUSES = {
    BEARING_WEAR:     { label: "Bearing wear (vibration-led)",        action: "Inspect and replace motor bearings; check shaft alignment and lubrication." },
    OVERHEATING:      { label: "Cooling failure / overheating",       action: "Check cooling fan and ventilation, clean the motor fins, verify ambient temperature." },
    OVERLOAD:         { label: "Mechanical / hydraulic overload",     action: "Reduce the hydraulic load: check for a blocked impeller or closed valve, verify supply voltage." },
    COMBINED_FAILURE: { label: "Combined multi-subsystem failure",    action: "Stop the unit and run a full inspection (bearings, cooling and load)." },
    NONE:             { label: "No fault detected",                   action: "No action needed." }
};

function region(sig, v) {                       // 0 normal, 1 warning, 2 critical
    if (sig === "rpm") {
        const dev = v < RPM.lo ? RPM.lo - v : v > RPM.hi ? v - RPM.hi : 0;
        return dev === 0 ? 0 : dev <= RPM.band ? 1 : 2;
    }
    return v > HI[sig].crit ? 2 : v > HI[sig].warn ? 1 : 0;
}
function anomaly(sig, v) {                      // 0..100: 0 normal, 0-50 warning zone, 50-100 critical zone
    let x;                                      // x = 0 at normal limit, 1 at critical limit, 2 = far past it
    if (sig === "rpm") {
        const dev = v < RPM.lo ? RPM.lo - v : v > RPM.hi ? v - RPM.hi : 0;
        x = dev / RPM.band;
    } else {
        const { warn, crit } = HI[sig];
        x = (v - warn) / (crit - warn);
    }
    return Math.max(0, Math.min(100, x * 50));
}
function linfit(xs, ys) {                       // least squares: slope and R2
    const n = xs.length, mx = xs.reduce((a, b) => a + b) / n, my = ys.reduce((a, b) => a + b) / n;
    let sxy = 0, sxx = 0, syy = 0;
    for (let i = 0; i < n; i++) { const dx = xs[i] - mx, dy = ys[i] - my; sxy += dx * dy; sxx += dx * dx; syy += dy * dy; }
    if (sxx === 0) return { slope: 0, r2: 0 };
    const slope = sxy / sxx;
    return { slope, r2: syy === 0 ? 0 : (sxy * sxy) / (sxx * syy) };
}
function band(risk) { return risk >= 61 ? "CRITICAL" : risk >= 31 ? "WARNING" : "NORMAL"; }
const r = (v, d = 2) => Math.round(v * 10 ** d) / 10 ** d;

const p = msg.payload, id = p.machine_id, t = Date.parse(p.timestamp) / 1000;
const fleet = flow.get("fleet") || {};
const m = fleet[id] || { ema: {}, win: [], state: "NORMAL", pending: null, pendingN: 0, n: 0, lastSeq: -1 };

// restart of the simulator resets seq -> start a fresh window
if (typeof p.seq === "number" && p.seq < m.lastSeq) { m.win = []; m.ema = {}; }
m.lastSeq = typeof p.seq === "number" ? p.seq : m.lastSeq;

// 1. smoothing + sliding window
const s = {};
for (const k of SIGNALS) { m.ema[k] = m.ema[k] === undefined ? p[k] : ALPHA * p[k] + (1 - ALPHA) * m.ema[k]; s[k] = m.ema[k]; }
m.win.push({ t, ...s }); if (m.win.length > WINDOW) m.win.shift();

// 2. weighted risk + single-signal safety floor
const regions = {}, anom = {};
let risk = 0;
for (const k of SIGNALS) { regions[k] = region(k, s[k]); anom[k] = anomaly(k, s[k]); risk += W[k] * anom[k]; }
const worst = Math.max(...Object.values(regions));
const maxAnom = Math.max(...Object.values(anom));
// safety floor: one bad signal can't be diluted by the healthy ones; floor grows with how far it is in its zone
if (worst === 2) risk = Math.max(risk, Math.min(100, 65 + 0.7 * (maxAnom - 50)));
else if (worst === 1) risk = Math.max(risk, Math.min(60, 35 + 0.5 * maxAnom));
risk = Math.round(Math.min(100, risk));
const health = 100 - risk;

// 3. state with confirmation (hysteresis)
let candidate = band(risk);
if (p.machine_status === "RECOVERING" && candidate !== "CRITICAL") candidate = "RECOVERING";
let changedFrom = null;
if (candidate !== m.state) {
    if (m.pending === candidate) m.pendingN++; else { m.pending = candidate; m.pendingN = 1; }
    if (m.pendingN >= CONFIRM) { changedFrom = m.state; m.state = candidate; m.pending = null; m.pendingN = 0; }
} else { m.pending = null; m.pendingN = 0; }

// 4. explainable fault cause (from sensors only, never sim_scenario)
const ab = k => regions[k] > 0;
const load = ab("current_a") || ab("rpm");
let cause = "NONE";
if (ab("vibration_rms") && load) cause = "COMBINED_FAILURE";
else if (ab("vibration_rms")) cause = "BEARING_WEAR";
else if (load) cause = "OVERLOAD";
else if (ab("temperature_c")) cause = "OVERHEATING";

// 5. dominant signal = biggest weighted contribution; if all normal, closest to its critical limit
let dominant = SIGNALS.reduce((a, b) => W[b] * anom[b] > W[a] * anom[a] ? b : a);
if (risk === 0 || W[dominant] * anom[dominant] === 0) {
    const closeness = k => k === "rpm" ? Math.max(RPM.lo - s.rpm, s.rpm - RPM.hi) / RPM.band : (s[k] - HI[k].warn) / (HI[k].crit - HI[k].warn);
    dominant = SIGNALS.reduce((a, b) => closeness(b) > closeness(a) ? b : a);
}

// 6. trustworthy TTC on the dominant signal
const xs = m.win.map(w => w.t), ys = m.win.map(w => w[dominant]);
let ttc = { value_s: null, label: "Unknown", reliable: false, signal: dominant, r2: null, slope: null, samples: m.win.length };
if (m.win.length >= 2) {
    const fit = linfit(xs, ys); ttc.r2 = r(fit.r2, 3); ttc.slope = r(fit.slope, 4);
    let limit, toward;
    if (dominant === "rpm") { limit = fit.slope < 0 ? RPM.lo - RPM.band : RPM.hi + RPM.band; toward = fit.slope !== 0; }
    else { limit = HI[dominant].crit; toward = fit.slope > 0; }
    const cur = s[dominant];
    const already = dominant === "rpm" ? regions.rpm === 2 : cur > limit;
    if (already) ttc = { ...ttc, value_s: 0, label: "Already critical", reliable: true };
    else if (m.win.length >= MIN_SAMPLES && fit.r2 >= R2_MIN && toward) {
        const sec = (limit - cur) / fit.slope;
        if (sec > 0 && isFinite(sec)) ttc = { ...ttc, value_s: Math.round(sec), label: `~${Math.round(sec)} s (estimated)`, reliable: true };
    }
}

m.n++; m.last = { ts: p.timestamp, seen: Date.now(), raw: { temperature_c: p.temperature_c, vibration_rms: p.vibration_rms, current_a: p.current_a, rpm: p.rpm },
    smoothed: Object.fromEntries(SIGNALS.map(k => [k, r(s[k])])), regions, anomaly: Object.fromEntries(SIGNALS.map(k => [k, r(anom[k], 1)])),
    risk, health, cause, cause_label: CAUSES[cause].label, action: CAUSES[cause].action, dominant, ttc, machine_status: p.machine_status };
if (!m.connectivity) m.connectivity = "ONLINE";
fleet[id] = m; flow.set("fleet", fleet);
node.status({ fill: m.state === "CRITICAL" ? "red" : m.state === "WARNING" ? "yellow" : "green", shape: "dot", text: `${id} ${m.state} risk ${risk}` });

const base = `factory/site01/machine/${id}`;
const out = [null, null, null, null, null, null, null];
if (m.n % PUBLISH_EVERY === 0 || changedFrom) {
    out[0] = { topic: `${base}/health`, payload: { machine_id: id, timestamp: p.timestamp, seq: p.seq, state: m.state, risk_score: risk, health_score: health,
        dominant_signal: dominant, likely_fault: cause, ttc_seconds: ttc.value_s, ttc_label: ttc.label, ttc_reliable: ttc.reliable, machine_status: p.machine_status } };
    out[1] = { topic: `${base}/features`, payload: { machine_id: id, timestamp: p.timestamp, seq: p.seq, window_size: m.win.length, smoothing: `EMA alpha=${ALPHA}`,
        moving_avg: m.last.smoothed, anomaly: m.last.anomaly, trend: { signal: dominant, slope_per_s: ttc.slope, r2: ttc.r2 } } };
}
if (changedFrom) {
    out[2] = { topic: `${base}/alerts`, payload: { machine_id: id, timestamp: p.timestamp, alert_type: "HEALTH_STATE", severity: m.state === "RECOVERING" ? "INFO" : m.state,
        previous_state: changedFrom, new_state: m.state, risk_score: risk, likely_fault: cause, dominant_signal: dominant, ttc_label: ttc.label } };
    if (m.state === "WARNING" || m.state === "CRITICAL") {
        out[3] = { topic: `${base}/actions`, payload: { machine_id: id, timestamp: p.timestamp, action_type: "RECOMMENDED", likely_fault: cause,
            recommended_action: CAUSES[cause].action, state: m.state, risk_score: risk, ttc_label: ttc.label } };
    }
    const log = flow.get("alertlog") || [];
    log.unshift({ time: p.timestamp, machine_id: id, from: changedFrom, to: m.state, text: `${CAUSES[cause].label} (risk ${risk})`, sev: m.state });
    flow.set("alertlog", log.slice(0, 15));
}
out[4] = { topic: id, payload: risk };
out[5] = { topic: id, payload: r(s.temperature_c, 1) };
out[6] = { topic: id, payload: r(s.vibration_rms, 2) };
return out;

const a = msg.payload;
msg.topic = `${a.machine_id}: ${a.new_state}`;
msg.payload = `${a.previous_state} -> ${a.new_state} | ${a.likely_fault} | risk ${a.risk_score} | TTC ${a.ttc_label}`;
return msg;

// [7] Runs once at deploy: fixes the series order (= colours) of the 3 charts and clears old points
const series = ["PUMP-01", "PUMP-02", "PUMP-03", "Warning limit", "Critical limit"];
const empty = () => ({ payload: [{ series, data: series.map(() => []), labels: [""] }] });
return [empty(), empty(), empty()];

// [3] Status / LWT handler (retained, QoS 1)
let d;
try { d = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload; } catch (e) { return null; }
if (!d || !d.machine_id) return null;
const fleet = flow.get("fleet") || {};
const m = fleet[d.machine_id] || { ema: {}, win: [], state: "NORMAL", pending: null, pendingN: 0, n: 0, lastSeq: -1 };
const offline = String(d.connectivity).toUpperCase() === "OFFLINE" || String(d.machine_status).toUpperCase() === "OFFLINE";
const before = m.connectivity;
m.connectivity = offline ? "OFFLINE" : "ONLINE";
m.reason = d.reason || "";
m.status_at = d.updated_at || new Date().toISOString();   // LWT has no updated_at -> receipt time
m.asset_name = d.asset_name || m.asset_name;
m.location = d.location || m.location;
fleet[d.machine_id] = m; flow.set("fleet", fleet);
if (before === m.connectivity) return null;               // retained duplicates: nothing new
if (before === undefined && !offline) return null;          // first retained ONLINE at startup: not an event
const unexpected = m.reason === "unexpected_disconnect_lwt";
const text = offline ? (unexpected ? "Connection lost (broker Last Will)" : "Stopped gracefully") : "Back online";
const log = flow.get("alertlog") || [];
log.unshift({ time: m.status_at, machine_id: d.machine_id, text, sev: offline ? "OFFLINE" : "ONLINE" });
flow.set("alertlog", log.slice(0, 15));
// The Kafka bridge already writes the CONNECTIVITY alert for an LWT, so we only notify the operator here.
if (!offline && before === undefined) return null;          // first retained ONLINE at startup: no toast
return { topic: `${d.machine_id}: ${offline ? "OFFLINE" : "ONLINE"}`, payload: text };

// [4] Fleet snapshot every second
// Outputs: 1 status panel, 2 event log, 3-5 limit lines for the risk / temperature / vibration charts
const fleet = flow.get("fleet") || {};
const now = Date.now();
const RANK = { OFFLINE: 4, CRITICAL: 3, WARNING: 2, RECOVERING: 1, NORMAL: 0 };
const ids = ["PUMP-01", "PUMP-02", "PUMP-03"];
for (const k of Object.keys(fleet)) if (!ids.includes(k)) ids.push(k);
const rows = ids.map(id => {
    const m = fleet[id] || {}, L = m.last || {};
    let state = m.state || "NORMAL";
    if (m.connectivity === "OFFLINE") state = "OFFLINE";
    const stale = L.seen ? (now - L.seen) > 5000 : true;
    return { id, state, stale: stale && state !== "OFFLINE", risk: L.risk ?? null, health: L.health ?? null,
        cause: L.cause || "NONE", cause_label: L.cause_label || "Waiting for data", action: L.action || "", dominant: L.dominant || "",
        ttc: L.ttc ? L.ttc.label : "Unknown", ttc_s: L.ttc && L.ttc.value_s !== null ? L.ttc.value_s : Infinity,
        raw: L.raw || {}, regions: L.regions || {}, machine_status: L.machine_status || "", reason: m.reason || "" };
});
rows.sort((a, b) => (RANK[b.state] - RANK[a.state]) || ((b.risk || 0) - (a.risk || 0)) || (a.ttc_s - b.ttc_s));
rows.forEach((x, i) => { x.priority = i + 1; if (x.ttc_s === Infinity) x.ttc_s = null; });
const online = rows.filter(x => x.state !== "OFFLINE").length;
const withHealth = rows.filter(x => x.health !== null && x.state !== "OFFLINE");
const avgHealth = withHealth.length ? Math.round(withHealth.reduce((a, x) => a + x.health, 0) / withHealth.length) : null;
const status = { payload: { rows, online, total: rows.length, avgHealth, updated: new Date().toISOString(),
    kpi: flow.get("kpi") || { accepted: 0, avoided_eur: 0 } } };
const events = { payload: { alerts: (flow.get("alertlog") || []).slice(0, 12), quarantine: (flow.get("quarantine") || []).slice(0, 4) } };
const lim = (w, c) => [{ topic: "Warning limit", payload: w }, { topic: "Critical limit", payload: c }];
return [status, events, lim(31, 61), lim(70, 80), lim(3, 6)];

// [5] Operator accepts maintenance -> command to the pump + action event to Kafka
// Estimated KPI: unplanned failure (~12,000 EUR) minus planned maintenance (~2,000 EUR)
const AVOIDED_PER_ACTION = 10000;
const id = msg.payload && msg.payload.machine_id;
if (!id) return null;
const fleet = flow.get("fleet") || {};
const m = fleet[id] || {}, L = m.last || {};
const now = Date.now();
if (m.lastAccept && now - m.lastAccept < 15000) { node.warn(`${id}: duplicate click ignored`); return null; }   // idempotent UI
m.lastAccept = now; fleet[id] = m; flow.set("fleet", fleet);
const ts = new Date(now).toISOString();
const action_id = `ACT-${id}-${now}`;
const counts = m.state === "WARNING" || m.state === "CRITICAL";
const kpi = flow.get("kpi") || { accepted: 0, avoided_eur: 0 };
kpi.accepted++; if (counts) kpi.avoided_eur += AVOIDED_PER_ACTION; flow.set("kpi", kpi);
const log = flow.get("alertlog") || [];
log.unshift({ time: ts, machine_id: id, text: `Maintenance accepted by operator (${action_id})`, sev: "ACTION" });
flow.set("alertlog", log.slice(0, 15));
const base = `factory/site01/machine/${id}`;
return [
    { topic: `${base}/command`, payload: { command: "accept_maintenance", action_id, requested_by: "nodered-dashboard", timestamp: ts } },
    { topic: `${base}/actions`, payload: { machine_id: id, timestamp: ts, action_type: "ACCEPTED", action_id, state_at_acceptance: m.state || "UNKNOWN",
        risk_score: L.risk ?? null, likely_fault: L.cause || "NONE", recommended_action: L.action || "", estimated_avoided_cost_eur: counts ? AVOIDED_PER_ACTION : 0,
        kpi_note: "ESTIMATED" } }
];

// [6] Demo control panel -> simulator commands
const pump = flow.get("ctl_pump") || "PUMP-03";
const scenario = flow.get("ctl_scenario") || "BEARING_WEAR";
const target = pump === "ALL" ? "all" : pump;
const topic = `factory/site01/machine/${target}/command`;
const ts = new Date().toISOString();
switch (msg.topic) {
    case "scenario":  return { topic, payload: { command: "set_scenario", scenario, timestamp: ts } };
    case "crash":     return pump === "ALL" ? null : { topic, payload: { command: "simulate_crash", timestamp: ts } };
    case "reconnect": return pump === "ALL" ? null : { topic, payload: { command: "reconnect", timestamp: ts } };
    case "normal":    return { topic, payload: { command: "set_scenario", scenario: "NORMAL", timestamp: ts } };
}
return null;
